// HD dialogue font.
//
// The standard message font is 16x16 CI4 glyphs, coloured at draw time through
// one of the game's 16-colour text palettes. Scaled to 720p/1080p they are
// hard to read. port/fonts/hd_standard.bin (generated by
// tools/switch/gen_hd_font.ps1 from an OFL font, not from the game) holds
// 64x64 replacements with the same palette index layout as the originals:
//   0 = transparent, 1 = body, 2..5 = edge ramp, 6 = outer halo.
// At draw time a glyph is expanded to RGBA32 through the palette the game asked
// for, so text colour, shadow and fade passes behave exactly as before.
//
// File layout (little endian):
//   char magic[4] = "PBHF"; u16 version = 1; u16 cell; u16 count; u16 reserved;
//   u8 present[count]; then cell*cell index bytes for every present glyph.

#include <cstring>
#include <memory>
#include <unordered_map>
#include <vector>

#include <libultraship/libultraship.h>
#include "port/ui/cvar_prefixes.h"

#include "common.h"
#include "port/patches/Patches.h"

extern "C" {
extern PAL_BIN D_802F4560[80][8];
void* GameEngine_GetDataExact(const char* name);
}

namespace {

constexpr int kVersion = 1;

struct HDFontData {
    bool loaded = false;
    bool valid = false;
    int cell = 0;
    std::vector<const uint8_t*> glyphs; // nullptr where the game glyph is kept
    std::shared_ptr<Ship::File> file;
};

HDFontData sFont;

// One RGBA32 buffer per (glyph, palette); never modified once built, so the
// renderer's address-keyed texture cache stays valid.
std::unordered_map<uint32_t, std::unique_ptr<uint32_t[]>> sExpanded;

void LoadFont() {
    sFont.loaded = true;
    auto archives = Ship::Context::GetRawInstance()->GetResourceManager()->GetArchiveManager();
    sFont.file = archives->LoadFile("fonts/hd_standard.bin");
    if (sFont.file == nullptr || sFont.file->Buffer == nullptr || sFont.file->Buffer->size() < 12) {
        SPDLOG_WARN("HD font: fonts/hd_standard.bin not found in the port archive");
        return;
    }
    const auto* data = reinterpret_cast<const uint8_t*>(sFont.file->Buffer->data());
    const size_t size = sFont.file->Buffer->size();
    auto u16 = [&](size_t offset) { return (uint16_t)(data[offset] | (data[offset + 1] << 8)); };
    if (memcmp(data, "PBHF", 4) != 0 || u16(4) != kVersion) {
        SPDLOG_WARN("HD font: bad header");
        return;
    }
    const int cell = u16(6);
    const int count = u16(8);
    size_t offset = 12 + (size_t)count;
    if (cell <= 0 || offset > size) {
        return;
    }
    sFont.cell = cell;
    sFont.glyphs.assign(count, nullptr);
    for (int i = 0; i < count; i++) {
        if (data[12 + i] == 0) {
            continue;
        }
        if (offset + (size_t)cell * cell > size) {
            SPDLOG_WARN("HD font: truncated file");
            sFont.glyphs.clear();
            return;
        }
        sFont.glyphs[i] = data + offset;
        offset += (size_t)cell * cell;
    }
    sFont.valid = true;
    SPDLOG_INFO("HD font: {} glyphs at {}x{}", count, cell, cell);
}

// RGBA5551 big-endian -> RGBA8888 (as the renderer reads RGBA32 texels: R,G,B,A bytes).
uint32_t ConvertColor(uint16_t c) {
    const uint8_t r = (uint8_t)(((c >> 11) & 0x1F) * 255 / 31);
    const uint8_t g = (uint8_t)(((c >> 6) & 0x1F) * 255 / 31);
    const uint8_t b = (uint8_t)(((c >> 1) & 0x1F) * 255 / 31);
    const uint8_t a = (c & 1) ? 255 : 0;
    const uint8_t bytes[4] = { r, g, b, a };
    uint32_t out;
    memcpy(&out, bytes, 4);
    return out;
}

} // namespace

extern "C" int port_msg_text_filter_is_sharp(void) {
    return CVarGetInteger(CVAR_DIALOGUE_TEXT_FILTER, DIALOGUE_TEXT_FILTER_DEFAULT) != 0;
}

extern "C" int port_msg_hd_font_cell(void) {
    return sFont.valid ? sFont.cell : 0;
}

// Returns the RGBA32 cell*cell replacement for a standard-font glyph drawn
// with the given palette, or nullptr to draw the game's own glyph.
extern "C" IMG_PTR port_msg_hd_glyph(s32 charIndex, s32 palette) {
    if (!CVarGetInteger(CVAR_HD_DIALOGUE_FONT, HD_DIALOGUE_FONT_DEFAULT)) {
        return nullptr;
    }
    if (!sFont.loaded) {
        LoadFont();
    }
    if (!sFont.valid || charIndex < 0 || charIndex >= (s32)sFont.glyphs.size() || palette < 0 || palette >= 80) {
        return nullptr;
    }
    const uint8_t* indices = sFont.glyphs[charIndex];
    if (indices == nullptr) {
        return nullptr;
    }

    const uint32_t key = ((uint32_t)palette << 16) | (uint32_t)charIndex;
    auto it = sExpanded.find(key);
    if (it != sExpanded.end()) {
        return reinterpret_cast<IMG_PTR>(it->second.get());
    }

    // The palette the game would load as TLUT, from the asset archive.
    const auto* pal = static_cast<const uint8_t*>(
        GameEngine_GetDataExact(reinterpret_cast<const char*>(port_msg_glyph_palette(D_802F4560[palette]))));
    if (pal == nullptr) {
        return nullptr;
    }
    uint32_t colors[16];
    for (int i = 0; i < 16; i++) {
        colors[i] = ConvertColor((uint16_t)((pal[i * 2] << 8) | pal[i * 2 + 1]));
    }

    const int texels = sFont.cell * sFont.cell;
    auto buffer = std::make_unique<uint32_t[]>(texels);
    for (int i = 0; i < texels; i++) {
        buffer[i] = colors[indices[i] & 0xF];
    }
    IMG_PTR result = reinterpret_cast<IMG_PTR>(buffer.get());
    sExpanded.emplace(key, std::move(buffer));
    return result;
}
